1: import axios, { create } from 'axios';
2: import { Platform } from 'react-native';
3: import { useAuthStore } from '@/store/auth-store';
4: 
5: const baseURL = process.env.EXPO_PUBLIC_API_URL?.trim().replace(/\/$/, '');
6: 
7: export const api = create({
8:   baseURL,
9:   timeout: 15_000,
10:   headers: {
11:     'Content-Type': 'application/json',
12:     'X-Kezza-Client': Platform.OS === 'web' ? 'web' : 'mobile',
13:   },
14:   withCredentials: true,
15: });
16: 
17: api.interceptors.request.use((config) => {
18:   if (!baseURL) {
19:     throw new Error('API address is not configured. Copy .env.example to .env and set EXPO_PUBLIC_API_URL.');
20:   }
21:   const token = useAuthStore.getState().accessToken;
22:   if (token) config.headers.Authorization = `Bearer ${token}`;
23:   return config;
24: });
25: 
26: api.interceptors.response.use(
27:   (response) => response,
28:   async (error) => {
29:     const original = error?.config as (typeof error.config & { _retry?: boolean }) | undefined;
30:     const isAuthRoute = String(original?.url ?? '').startsWith('/auth/');
31:     if (error?.response?.status === 401 && original && !original._retry && !isAuthRoute && baseURL) {
32:       const refreshToken = useAuthStore.getState().refreshToken;
33:       if (refreshToken || typeof document !== 'undefined') {
34:         original._retry = true;
35:         try {
36:           const refreshed = await axios.post<{ access_token: string; refresh_token?: string }>(
37:             `${baseURL}/auth/refresh`, { refresh_token: refreshToken }, {
38:               withCredentials: true,
39:               timeout: 15_000,
40:               headers: { 'X-Kezza-Client': Platform.OS === 'web' ? 'web' : 'mobile' },
41:             },
42:           );
43:           await useAuthStore.getState().updateTokens(refreshed.data.access_token, refreshed.data.refresh_token);
44:           original.headers.Authorization = `Bearer ${refreshed.data.access_token}`;
45:           return api(original);
46:         } catch {
47:           await useAuthStore.getState().signOut();
48:         }
49:       } else {
50:         await useAuthStore.getState().signOut();
51:       }
52:     }
53:     if (error?.response?.status === 401 && !isAuthRoute) await useAuthStore.getState().signOut();
54:     return Promise.reject(error);
55:   },
56: );

