1: import * as SecureStore from 'expo-secure-store';
2: import { Platform } from 'react-native';
3: import { create } from 'zustand';
4: 
5: export type AgentUser = {
6:   id: string;
7:   fullName: string;
8:   phone: string;
9:   role: string;
10:   agentId: string;
11:   agentCode?: string;
12:   branchId?: string;
13: };
14: 
15: type AuthState = {
16:   isHydrated: boolean;
17:   accessToken: string | null;
18:   refreshToken: string | null;
19:   user: AgentUser | null;
20:   hydrate: () => Promise<void>;
21:   signIn: (token: string, user: AgentUser, refreshToken?: string) => Promise<void>;
22:   updateTokens: (token: string, refreshToken?: string) => Promise<void>;
23:   signOut: () => Promise<void>;
24: };
25: 
26: const TOKEN_KEY = 'kezza_agent_access_token';
27: const REFRESH_TOKEN_KEY = 'kezza_agent_refresh_token';
28: const USER_KEY = 'kezza_agent_user';
29: 
30: async function getItem(key: string) {
31:   if (Platform.OS === 'web') return localStorage.getItem(key);
32:   try { return await SecureStore.getItemAsync(key); } catch { return null; }
33: }
34: async function setItem(key: string, value: string) {
35:   if (Platform.OS === 'web') { localStorage.setItem(key, value); return; }
36:   await SecureStore.setItemAsync(key, value);
37: }
38: async function removeItem(key: string) {
39:   if (Platform.OS === 'web') { localStorage.removeItem(key); return; }
40:   try { await SecureStore.deleteItemAsync(key); } catch { /* The local session is still cleared. */ }
41: }
42: 
43: export const useAuthStore = create<AuthState>((set) => ({
44:   isHydrated: false,
45:   accessToken: null,
46:   refreshToken: null,
47:   user: null,
48:   hydrate: async () => {
49:     try {
50:       const [token, refreshToken, userJson] = await Promise.all([getItem(TOKEN_KEY), getItem(REFRESH_TOKEN_KEY), getItem(USER_KEY)]);
51:       if (token && userJson) {
52:         const user = JSON.parse(userJson) as AgentUser;
53:         if (user.agentId) set({ accessToken: token, refreshToken, user });
54:       }
55:     } catch { /* Treat invalid saved data as a signed-out session. */ }
56:     finally { set({ isHydrated: true }); }
57:   },
58:   signIn: async (accessToken, user, refreshToken) => {
59:     await Promise.all([setItem(TOKEN_KEY, accessToken), setItem(USER_KEY, JSON.stringify(user)),
60:       refreshToken ? setItem(REFRESH_TOKEN_KEY, refreshToken) : removeItem(REFRESH_TOKEN_KEY)]);
61:     set({ accessToken, refreshToken: refreshToken ?? null, user });
62:   },
63:   updateTokens: async (accessToken, refreshToken) => {
64:     await setItem(TOKEN_KEY, accessToken);
65:     if (refreshToken) await setItem(REFRESH_TOKEN_KEY, refreshToken);
66:     set({ accessToken, refreshToken: refreshToken ?? useAuthStore.getState().refreshToken });
67:   },
68:   signOut: async () => {
69:     await Promise.all([removeItem(TOKEN_KEY), removeItem(REFRESH_TOKEN_KEY), removeItem(USER_KEY)]);
70:     set({ accessToken: null, refreshToken: null, user: null });
71:   },
72: }));
